        self.script_count = 0
        self.canvas_count = 0

    def handle_starttag(self, tag, attrs):
        if tag not in ['meta', 'link', 'br', 'hr', 'img', 'input', 'canvas']:
            self.tags.append(tag)
        if tag == 'title':
            self.has_title = True
        if tag == 'body':
